changeSet.sql:
CREATE TABLE IF NOT EXISTS "log".activity_log
(
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    user_id UUID,
    company_id UUID,
    activity TEXT,
    data JSON,
    created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_activity_log_user_id ON "log".activity_log (user_id);
CREATE INDEX IF NOT EXISTS idx_activity_log_activity ON "log".activity_log (activity);
CREATE INDEX IF NOT EXISTS idx_activity_log_created ON "log".activity_log (created_date);
